<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, toRaw, watch } from 'vue'
import {
  useOverlayStore,
  type AppConfig,
  type DeathEvent,
  type MediaEvent,
  type PlayedSong,
  type ZoneEvent,
} from '@/stores/overlay'
import { playSound, SOUND_NAMES } from '@/audio/sounds'

// store: the shared Pinia store instance. useOverlayStore is
// generated by defineStore() in stores/overlay.ts. Calling it
// returns the SAME store (socket + state) that every other
// component gets, so ControlView and the overlay page share one.
const store = useOverlayStore()

// --- tabs ---------------------------------------------------------------
// Plain state rather than separate routes: the settings tab shares the draft,
// save logic and store with everything else here. Paired with v-show (not
// v-if) in the template, so switching tabs mid-edit keeps an unsaved draft.
type Tab = 'live' | 'songs' | 'settings'
const tab = ref<Tab>('live')

// --- backend health -----------------------------------------------------
// apiOk is a tri-state: null while the first check is in flight, then
// true/false. A dashboard light that says "down" before it has looked is
// worse than one that says nothing yet.
const apiOk = ref<boolean | null>(null)

async function checkHealth() {
  try {
    const res = await fetch('/api/health')
    apiOk.value = res.ok && (await res.json()).status === 'ok'
  } catch {
    apiOk.value = false
  }
}

// Polled rather than checked once: the panel usually stays open all stream,
// and a backend restart should light up here without a manual refresh.
let healthTimer: ReturnType<typeof setInterval> | undefined

onMounted(async () => {
  store.connect() // open (or reuse) the WebSocket
  checkHealth()
  void loadMnm()
  void loadMedia()
  healthTimer = setInterval(() => {
    checkHealth()
    void loadMnm()
  }, 10_000)
  // Fire and forget: OBS may not be running, and that must not hold up the
  // rest of the dashboard loading.
  void loadScenes()
  // Seeds the activity feed from disk so a refresh or a backend restart
  // doesn't blank it.
  void store.loadActivity()
  void store.loadDeaths()
  void store.loadSongs()
  await store.loadConfig()
  draft.value = structuredClone(toRaw(store.config))
})

// The song queue is state, never replayed over /ws, so a backend restart or a
// dropped socket would otherwise leave the card showing a stale queue.
watch(
  () => store.connected,
  (up) => {
    if (up) void store.loadSongs()
  },
)

// Intervals outlive the component unless you say otherwise, and would keep
// polling (and writing to a dead ref) after navigating away.
onUnmounted(() => clearInterval(healthTimer))

// --- test alerts --------------------------------------------------------
const alertText = ref('New Follower: Innoruuk')

// The configured kinds drive the quick-fire buttons, so adding a kind to
// config.json gives you a test button for it for free.
const kindNames = computed(() => Object.keys(store.config?.alerts.kinds ?? {}))

function sendAlert(kind?: string) {
  store.send({
    type: 'alert',
    kind,
    text: alertText.value || `Test ${kind ?? 'alert'}`,
  })
}

// --- widget settings (Phase 8) ------------------------------------------
// Edited against a local draft rather than the store, so a half-typed colour
// doesn't get pushed to the overlay until you actually hit Save.
const draft = ref<AppConfig | null>(null)
const configStatus = ref('')

async function saveConfig() {
  if (!draft.value || !store.config) return
  configStatus.value = 'saving…'
  // Only the alerts section comes from the draft. The rest is taken from the
  // store, which config broadcasts keep current. The draft was cloned when the
  // page loaded, so sending it whole would quietly undo anything changed
  // since -- like opening song requests from the Song Requests card.
  const body = { ...toRaw(store.config), alerts: draft.value.alerts }
  try {
    const res = await fetch('/api/config', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })
    const data = await res.json()
    configStatus.value = res.ok ? 'saved' : `error: ${JSON.stringify(data.detail)}`
  } catch (e) {
    configStatus.value = `network error: ${e}`
  }
}

// Undo without a round trip: the store's copy is whatever the backend last
// confirmed, so cloning it again throws away unsaved edits.
function revertConfig() {
  draft.value = structuredClone(toRaw(store.config))
  configStatus.value = 'reverted'
}

// --- OBS control (Phase 6) ----------------------------------------------
const obsScene = ref('')
const obsStatus = ref('') // last result/error, shown under the buttons
const obsOk = ref<boolean | null>(null)

// Populated from OBS itself, so you pick from what exists rather than typing
// a name and only finding out it was wrong when OBS rejects it.
interface ObsSource {
  name: string
  visible: boolean
}
const obsScenes = ref<string[]>([])
const obsSources = ref<ObsSource[]>([])
const obsLoading = ref(false)
// OBS being closed is normal and not an error worth shouting about — the
// dropdowns just stay empty until you press Reload.
const obsReachable = ref<boolean | null>(null)

async function loadScenes() {
  obsLoading.value = true
  try {
    const res = await fetch('/api/obs/scenes')
    if (!res.ok) throw new Error((await res.json()).detail ?? res.statusText)
    const data = await res.json()
    obsScenes.value = data.scenes
    obsReachable.value = true
    // Default to whatever is live, so the panel opens on the current scene.
    if (!obsScene.value || !data.scenes.includes(obsScene.value)) {
      obsScene.value = data.current ?? data.scenes[0] ?? ''
    }
    await loadSources()
  } catch (e) {
    obsReachable.value = false
    obsScenes.value = []
    obsSources.value = []
    obsStatus.value = `${e}`
  } finally {
    obsLoading.value = false
  }
}

async function loadSources() {
  if (!obsScene.value) {
    obsSources.value = []
    return
  }
  try {
    const res = await fetch(`/api/obs/sources?scene=${encodeURIComponent(obsScene.value)}`)
    if (!res.ok) throw new Error((await res.json()).detail ?? res.statusText)
    obsSources.value = (await res.json()).sources
  } catch (e) {
    obsSources.value = []
    obsStatus.value = `${e}`
  }
}

// Sources are per scene in OBS -- the same source carries a different
// visibility in each -- so the list reloads whenever the scene changes.
watch(obsScene, loadSources)

// Each checkbox is bound one-way (:checked, not v-model): the browser ticks
// the box the moment it's clicked, but the truth lives in OBS. So re-read the
// scene afterwards rather than trusting the click -- if OBS refused the
// change, loadSources() puts the box back to what OBS actually did.
async function setSourceVisible(source: string, visible: boolean) {
  await callObs('/api/obs/source', {
    scene: obsScene.value,
    source,
    visible,
  })
  await loadSources()
}

// POST a JSON body to one of our /api/obs endpoints and report how it went.
async function callObs(path: string, body: object) {
  obsStatus.value = 'sending…'
  try {
    const res = await fetch(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })
    const data = await res.json()
    // FastAPI puts error text in `detail`; our success path returns `ok: true`.
    obsOk.value = res.ok
    obsStatus.value = res.ok ? `ok: ${JSON.stringify(data)}` : `error: ${data.detail}`
  } catch (e) {
    obsOk.value = false
    obsStatus.value = `network error: ${e}`
  }
}

// --- panic ----------------------------------------------------------------
// Clears every queue and hides everything on both overlays. Exists because
// when a clip is blaring at the wrong moment you do not want to be alt-tabbing
// to a terminal.
const panicStatus = ref('')

async function panic() {
  panicStatus.value = 'stopping…'
  try {
    const res = await fetch('/api/panic', { method: 'POST' })
    panicStatus.value = res.ok ? 'overlays cleared' : `error: ${res.status}`
  } catch (e) {
    panicStatus.value = `network error: ${e}`
  }
  setTimeout(() => (panicStatus.value = ''), 4000)
}

// --- bot chat (Phase 12) -------------------------------------------------
// Posts as the bot account, not you. The backend's error detail already says
// why a message didn't go (not connected / rate limited / Twitch refused it),
// so it's shown as-is.
const chatText = ref('')
const chatStatus = ref('')

async function postChat(text: string): Promise<string | null> {
  try {
    const res = await fetch('/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text }),
    })
    if (res.ok) return null
    const body = await res.json().catch(() => ({}))
    return typeof body.detail === 'string' ? body.detail : `error: ${res.status}`
  } catch (e) {
    return `network error: ${e}`
  }
}

async function sendChat() {
  const text = chatText.value.trim()
  if (!text) return
  const err = await postChat(text)
  chatStatus.value = err ?? 'sent'
  if (!err) chatText.value = ''
  setTimeout(() => (chatStatus.value = ''), 4000)
}

// The Phase 12 checkpoint: 30 sends against a 20-per-30s limit. Expect about
// 20 through and the rest refused by our own limiter, with nothing erroring.
async function chatBurst() {
  chatStatus.value = 'bursting…'
  let sent = 0
  let limited = 0
  let other = ''
  for (let i = 1; i <= 30; i++) {
    const err = await postChat(`burst test ${i}/30`)
    if (err === null) sent++
    else if (err === 'rate limited') limited++
    else other = err
  }
  chatStatus.value = `${sent} sent, ${limited} rate limited${other ? `, last error: ${other}` : ''}`
  setTimeout(() => (chatStatus.value = ''), 8000)
}

// --- song requests (Phase 13d) ---------------------------------------------
// The queue lives on the backend. Every button here just asks for a change;
// the backend broadcasts the new state, and store.songs (which this card
// renders) follows it -- the same way the overlay does. So the card can never
// show a queue the overlay disagrees with.
const songStatus = ref('')
const songLink = ref('')
const songVolume = ref(50)

// The slider is a local copy, synced from config whenever config changes,
// so dragging it isn't fighting a value being rewritten under it.
watch(
  () => store.config?.songs?.volume,
  (v) => {
    if (typeof v === 'number') songVolume.value = v
  },
  { immediate: true },
)

async function songCall(path: string, init: RequestInit = { method: 'POST' }) {
  songStatus.value = ''
  try {
    const res = await fetch(path, init)
    if (!res.ok) {
      const body = await res.json().catch(() => ({}))
      songStatus.value = typeof body.detail === 'string' ? body.detail : `error: ${res.status}`
      return false
    }
    return true
  } catch (e) {
    songStatus.value = `network error: ${e}`
    return false
  }
}

function songSettings(change: { enabled?: boolean; volume?: number }) {
  return songCall('/api/songs/settings', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(change),
  })
}

// Runs the same code as `!sr`, as you: handy for queueing your own song.
async function requestSong() {
  const text = songLink.value.trim()
  if (!text) return
  const ok = await songCall('/api/songs/request', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text, user: 'broadcaster' }),
  })
  if (ok) songLink.value = ''
}

function removeSong(requestId: string) {
  void songCall(`/api/songs/${encodeURIComponent(requestId)}`, { method: 'DELETE' })
}

// Tag colours for the Played list, from the dashboard's own palette: green
// finished, dim skipped, red failed, orange removed.
const outcomeColor: Record<PlayedSong['outcome'], string> = {
  played: '#50fa7b',
  skipped: '#6272a4',
  failed: '#ff5555',
  removed: '#ffb86c',
}

function duration(seconds: number) {
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`
}

// --- death counter (Phase 14) ------------------------------------------
// The count itself comes from the game's Ledger on the backend; these only
// move the session's start or nudge the total. Each POST is answered with the
// new state, and the backend broadcasts it too, so the overlay follows along.
const deathStatus = ref('')

async function deathCall(path: string, body?: object) {
  deathStatus.value = ''
  try {
    const res = await fetch(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: body ? JSON.stringify(body) : undefined,
    })
    if (res.ok) store.deaths = await res.json()
    else deathStatus.value = `error: ${res.status}`
  } catch (e) {
    deathStatus.value = `network error: ${e}`
  }
}

function newStream() {
  if (!confirm('Start a new stream? The death count goes back to 0.')) return
  void deathCall('/api/deaths/reset')
}

// Rides the relay like a test alert, flagged so the overlay previews the
// flare and bell on a fake +1 without the real count ever changing.
function testDeath() {
  const event: DeathEvent = {
    type: 'death',
    test: true,
    count: (store.deaths?.count ?? 0) + 1,
    character: 'Test',
    zone: 'the Underdark',
    text: 'Test death',
  }
  store.send(event)
}

// --- M&M watchers ---------------------------------------------------------
// A Test button only proves an overlay can draw. These answer the other half
// of "is it working?": is the backend actually reading the game? Zone comes
// from Player.log, the last Ledger event from SQLite -- if either looks stale
// while you're playing, the watcher is the problem, not the overlay.
interface ZoneState {
  zone: string | null
  name: string | null
  lore: string
  watching: string | null // Player.log's path, or null if M&M wasn't found
}
interface LedgerRow {
  at: string
  actor: string
  kind: string
  item?: string | null
  mob?: string | null
}
const zoneState = ref<ZoneState | null>(null)
const lastLedger = ref<LedgerRow | null>(null)

async function loadMnm() {
  try {
    const [zone, recent] = await Promise.all([
      fetch('/api/zone'),
      fetch('/api/ledger/recent?limit=1'),
    ])
    if (zone.ok) zoneState.value = await zone.json()
    if (recent.ok) lastLedger.value = (await recent.json())[0] ?? null
  } catch {
    // Backend down: the API pill already says so.
  }
}

// The last *real* banner the relay sent. The feed already holds it (restored
// from activity.json on load), so nothing new needs storing. Test zones are
// skipped: they'd make the watcher look alive when it isn't.
const lastBanner = computed(() =>
  store.recentEvents.find((e) => e.type === 'zone' && !('test' in e && e.test)),
)

// A live zone-in updates the card at once rather than on the next poll.
watch(
  () => store.lastEvent,
  (event) => {
    if (event?.type !== 'zone' || (event as ZoneEvent).test || !zoneState.value) return
    const { zone, name, lore } = event as ZoneEvent
    zoneState.value = { ...zoneState.value, zone, name, lore }
  },
)

// The zone banner's preview. Uses where you really are, when the backend
// knows, so it doubles as a check on that zone's name and lore line.
async function testZone() {
  await loadMnm()
  const here = zoneState.value
  const zone = here?.zone
    ? { zone: here.zone, name: here.name ?? here.zone, lore: here.lore }
    : { zone: 'underdark', name: 'The Underdark', lore: 'A test of the zone banner.' }
  const event: ZoneEvent = { type: 'zone', test: true, ...zone, text: `Test zone: ${zone.name}` }
  store.send(event)
}

// The shape ledger.py sends for a real level-up -- user and the new level in
// `amount` -- so this tests the overlay's handling of that, not just the
// level_up kind's colour and sound (the kind button above does only that).
function testLevelUp() {
  store.send({
    type: 'alert',
    kind: 'level_up',
    user: 'Sanguine',
    amount: 22,
    text: 'Sanguine reached level 22',
  })
}

// --- clip tester ------------------------------------------------------------
// Sends exactly what twitch.py sends for a media redeem, minus Twitch. Lists
// files on disk, not routed rewards, so a clip can be checked in OBS (codec,
// volume, framing) before a reward ever points at it.
const mediaFiles = ref<string[]>([])
const mediaPick = ref('')

async function loadMedia() {
  try {
    const res = await fetch('/api/media')
    if (!res.ok) return
    mediaFiles.value = (await res.json()).files
    if (!mediaFiles.value.includes(mediaPick.value)) mediaPick.value = mediaFiles.value[0] ?? ''
  } catch {
    // No backend; the dropdown stays empty.
  }
}

function testMedia(interrupt: boolean) {
  if (!mediaPick.value) return
  const event: MediaEvent = {
    type: 'media',
    src: `/media/${mediaPick.value}`,
    title: mediaPick.value,
    user: 'Test',
    interrupt,
    text: `Test clip: ${mediaPick.value}`,
  }
  store.send(event)
}

function sinceTime(iso?: string) {
  return iso ? clockTime(Date.parse(iso)) : '—'
}

// --- activity feed ------------------------------------------------------
function clockTime(at: number) {
  return new Date(at).toLocaleTimeString([], { hour12: false })
}

// Feed rows borrow the alert's own accent colour, so a raid and a follow are
// tellable apart at a glance from across the room.
function accentFor(kind?: string) {
  return store.config?.alerts.kinds[kind || 'generic']?.accent ?? '#6272a4'
}
</script>

<template>
  <main class="dash">
    <header class="topbar">
      <h1>SANG SUITE</h1>
      <nav class="tabs">
        <button :class="{ active: tab === 'live' }" @click="tab = 'live'">Live</button>
        <button :class="{ active: tab === 'songs' }" @click="tab = 'songs'">Song Requests</button>
        <button :class="{ active: tab === 'settings' }" @click="tab = 'settings'">Alert Settings</button>
      </nav>
      <div class="pills">
        <span class="pill" :class="apiOk === null ? 'idle' : apiOk ? 'up' : 'down'">
          API {{ apiOk === null ? '…' : apiOk ? 'ok' : 'down' }}
        </span>
        <span class="pill" :class="store.connected ? 'up' : 'down'">
          WS {{ store.connected ? 'live' : 'offline' }}
        </span>
        <span class="pill" :class="obsOk === null ? 'idle' : obsOk ? 'up' : 'down'">
          OBS {{ obsOk === null ? 'untested' : obsOk ? 'ok' : 'error' }}
        </span>
      </div>
    </header>

    <div v-show="tab === 'live'" class="grid">
      <section class="card panic-card">
        <h2>Panic</h2>
        <p class="hint">Clears every queue and hides both overlays immediately.</p>
        <div class="row">
          <button class="panic" @click="panic">STOP EVERYTHING</button>
          <span v-if="panicStatus" class="status">{{ panicStatus }}</span>
        </div>
      </section>

      <section class="card">
        <h2>Test Alerts</h2>
        <label class="field">
          <span>Message</span>
          <input v-model="alertText" placeholder="New Follower: Innoruuk" />
        </label>
        <div class="row">
          <button class="primary" @click="sendAlert()">Send</button>
          <!-- No `kind` on the plain Send above, so it uses the overlay's
               'generic' styling; these fire a specific kind instead. -->
          <button v-for="name in kindNames" :key="name" @click="sendAlert(name)">
            {{ name }}
          </button>
        </div>
      </section>

      <section class="card">
        <h2>Bot Chat</h2>
        <p class="hint">Posts to your Twitch chat as the bot account.</p>
        <label class="field">
          <span>Message</span>
          <input v-model="chatText" placeholder="Hello, chat" maxlength="500" @keyup.enter="sendChat" />
        </label>
        <div class="row">
          <button class="primary" @click="sendChat">Send</button>
          <button @click="chatBurst">Burst ×30</button>
          <span v-if="chatStatus" class="status">{{ chatStatus }}</span>
        </div>
      </section>

      <section class="card">
        <h2>
          OBS Control
          <span class="status inline">
            {{ obsLoading ? 'loading…' : obsReachable === false ? 'OBS not reachable' : '' }}
          </span>
        </h2>
        <label class="field">
          <span>Scene</span>
          <select v-model="obsScene" :disabled="!obsScenes.length">
            <option v-if="!obsScenes.length" value="">— no scenes —</option>
            <option v-for="name in obsScenes" :key="name" :value="name">{{ name }}</option>
          </select>
        </label>
        <!-- One checkbox per source in the selected scene: ticked = visible.
             It's a snapshot from the last load, not live -- OBS doesn't push
             changes to us, hence the reload button below. -->
        <fieldset class="field sources">
          <legend>Sources</legend>
          <p v-if="!obsSources.length" class="hint">— no sources —</p>
          <div class="source-list">
            <label v-for="s in obsSources" :key="s.name" class="check" :title="s.name">
              <input
                type="checkbox"
                :checked="s.visible"
                @change="setSourceVisible(s.name, ($event.target as HTMLInputElement).checked)"
              />
              <span>{{ s.name }}</span>
            </label>
          </div>
        </fieldset>
        <div class="row">
          <button
            class="primary"
            :disabled="!obsScene"
            @click="callObs('/api/obs/scene', { scene: obsScene })"
          >
            Switch Scene
          </button>
          <!-- Scenes and sources change in OBS while this page is open, and
               nothing pushes that to us, so there has to be a manual reload. -->
          <button class="icon" title="Reload from OBS" @click="loadScenes">⟳</button>
        </div>
        <p class="status">{{ obsStatus || '—' }}</p>
      </section>

      <section class="card">
        <h2>
          Death Counter
          <span class="status inline">
            {{ store.deaths && !store.deaths.watching ? 'M&M not found' : '' }}
          </span>
        </h2>
        <p class="death-count">{{ store.deaths?.count ?? '…' }}</p>
        <p class="hint">
          Since {{ sinceTime(store.deaths?.session_start) }}
          <template v-if="store.deaths?.last">
            · last: {{ store.deaths.last.character }} in {{ store.deaths.last.zone }}
            at {{ sinceTime(store.deaths.last.at) }}
          </template>
        </p>
        <div class="row">
          <button class="primary" @click="newStream">New Stream</button>
          <!-- For when the Ledger gets it wrong: it can't tell us about deaths
               it didn't record, and act_02 might cover more than dying. -->
          <button class="icon" title="One fewer" @click="deathCall('/api/deaths/adjust', { delta: -1 })">−1</button>
          <button class="icon" title="One more" @click="deathCall('/api/deaths/adjust', { delta: 1 })">+1</button>
          <button @click="testDeath">Test Death</button>
        </div>
        <p class="status">{{ deathStatus || 'OBS source: localhost:8000/overlay/deaths (420 × 180)' }}</p>
      </section>

      <section class="card">
        <h2>
          Monsters &amp; Memories
          <span class="status inline">{{ zoneState && !zoneState.watching ? 'Player.log not found' : '' }}</span>
        </h2>
        <!-- Status first, buttons second: if "In" is right and "Last banner"
             matches your last zone, the backend fired and any missing banner
             is OBS's side (source URL, visibility, a stale page). -->
        <dl class="facts">
          <dt>In</dt>
          <dd>{{ zoneState?.name ?? '—' }}</dd>
          <dt>Last banner</dt>
          <dd>
            <template v-if="lastBanner">{{ clockTime(lastBanner.at) }} · {{ lastBanner.text }}</template>
            <template v-else>none in the feed</template>
          </dd>
          <dt>Ledger</dt>
          <dd>
            <template v-if="lastLedger">
              {{ sinceTime(lastLedger.at) }} · {{ lastLedger.actor }}: {{ lastLedger.kind }}
              {{ lastLedger.item ?? '' }}
            </template>
            <template v-else>no events yet</template>
          </dd>
        </dl>
        <div class="row">
          <button class="primary" @click="testZone">Test Zone</button>
          <button @click="testLevelUp">Test Level Up</button>
          <button class="icon" title="Refresh" @click="loadMnm">⟳</button>
        </div>
        <p class="status">Zone banner: localhost:8000/overlay/zone (1920 × 300, bottom)</p>
      </section>

      <section class="card">
        <h2>
          Test Clips
          <span class="status inline">{{ mediaFiles.length }} file(s)</span>
        </h2>
        <label class="field">
          <span>Clip</span>
          <select v-model="mediaPick" :disabled="!mediaFiles.length">
            <option v-if="!mediaFiles.length" value="">— nothing in backend/media —</option>
            <option v-for="f in mediaFiles" :key="f" :value="f">{{ f }}</option>
          </select>
        </label>
        <div class="row">
          <button class="primary" :disabled="!mediaPick" @click="testMedia(false)">Queue</button>
          <!-- Interrupt cuts off whatever is playing, as an interrupt reward
               would; Queue waits its turn. -->
          <button :disabled="!mediaPick" @click="testMedia(true)">Interrupt</button>
          <button class="icon" title="Rescan backend/media" @click="loadMedia">⟳</button>
        </div>
        <p class="status">Media overlay: localhost:8000/overlay/media</p>
      </section>

      <section class="card wide">
        <h2>
          Activity
          <span class="status inline">{{ store.recentEvents.length }} event(s)</span>
        </h2>
        <p v-if="!store.recentEvents.length" class="status">
          Nothing yet — fire a test alert or wait for Twitch.
        </p>
        <ul class="feed">
          <li v-for="event in store.recentEvents" :key="event.id">
            <span class="time">{{ clockTime(event.at) }}</span>
            <span class="tag" :style="{ color: accentFor(event.kind), borderColor: accentFor(event.kind) }">
              {{ event.kind || event.type }}
            </span>
            <span class="text">{{ event.text }}</span>
            <span class="amount">{{ event.amount ?? '' }}</span>
          </li>
        </ul>
      </section>
    </div>

    <div v-show="tab === 'songs'" class="grid">
      <section class="card songs-card">
        <h2>
          Song Requests
          <span class="status inline" :class="store.config?.songs?.enabled ? 'open' : 'closed'">
            {{ store.config?.songs?.enabled ? 'open' : 'closed' }}
          </span>
        </h2>
        <div class="row">
          <!-- Announced in chat by the bot when it changes. -->
          <button
            class="primary"
            @click="songSettings({ enabled: !store.config?.songs?.enabled })"
          >
            {{ store.config?.songs?.enabled ? 'Close requests' : 'Open requests' }}
          </button>
          <label class="field grow">
            <span>Volume — {{ songVolume }}%</span>
            <!-- Saved on release (change), not on every pixel of the drag
                 (input), which would write config.json dozens of times. -->
            <input
              v-model.number="songVolume"
              type="range"
              min="0"
              max="100"
              step="5"
              @change="songSettings({ volume: songVolume })"
            />
          </label>
        </div>

        <div class="now-playing">
          <template v-if="store.songs?.now">
            <span class="np-label">{{ store.songs.paused ? 'PAUSED' : 'NOW PLAYING' }}</span>
            <!-- Viewer-chosen text: interpolation only, never v-html. -->
            <a
              class="np-title"
              :href="`https://youtu.be/${store.songs.now.video_id}`"
              target="_blank"
              rel="noopener"
            >{{ store.songs.now.title }}</a>
            <span class="hint">
              {{ store.songs.now.channel }} · {{ duration(store.songs.now.duration_s) }} ·
              requested by {{ store.songs.now.user }}
            </span>
          </template>
          <span v-else class="hint">Nothing playing.</span>
        </div>

        <div class="row">
          <button
            v-if="store.songs?.paused"
            class="primary"
            @click="songCall('/api/songs/resume')"
          >
            Resume
          </button>
          <button v-else @click="songCall('/api/songs/pause')">Pause</button>
          <button :disabled="!store.songs?.now" @click="songCall('/api/songs/skip')">Skip</button>
        </div>

        <ol v-if="store.songs?.queue.length" class="song-queue">
          <li v-for="song in store.songs.queue" :key="song.request_id">
            <span class="sq-title" :title="song.title">{{ song.title }}</span>
            <span class="sq-meta">{{ song.user }} · {{ duration(song.duration_s) }}</span>
            <button class="icon" title="Remove" @click="removeSong(song.request_id)">✕</button>
          </li>
        </ol>
        <p v-else class="hint">Queue is empty.</p>

        <label class="field">
          <span>Request a song</span>
          <input v-model="songLink" placeholder="youtube link" @keyup.enter="requestSong" />
        </label>
        <p class="status">
          {{ songStatus || 'Song overlay: localhost:8000/overlay/song' }}
        </p>
      </section>

      <section class="card wide">
        <h2>
          Played
          <span class="status inline">{{ store.songs?.history.length ?? 0 }} song(s)</span>
        </h2>
        <p v-if="!store.songs?.history.length" class="status">
          Nothing played yet. Songs land here once they leave "now playing".
        </p>
        <!-- Same markup and styling as the activity feed: time, tag, text,
             and a dim right-hand column. -->
        <ul class="feed">
          <li v-for="song in store.songs?.history" :key="song.request_id">
            <span class="time">{{ clockTime(song.started_at ?? song.ended_at) }}</span>
            <span
              class="tag"
              :style="{ color: outcomeColor[song.outcome], borderColor: outcomeColor[song.outcome] }"
              :title="song.detail ?? ''"
            >
              {{ song.outcome }}
            </span>
            <span class="text">
              <a class="np-title" :href="`https://youtu.be/${song.video_id}`" target="_blank" rel="noopener">{{
                song.title
              }}</a>
              <span class="sq-meta">requested by {{ song.user }}</span>
            </span>
            <span class="amount">{{ duration(song.duration_s) }}</span>
          </li>
        </ul>
      </section>
    </div>

    <div v-show="tab === 'settings'" class="grid">
      <section class="card wide" v-if="draft">
        <h2>
          Alert Settings
          <span class="status inline">{{ configStatus }}</span>
        </h2>
        <div class="row">
          <label class="field">
            <span>Duration (ms)</span>
            <input v-model.number="draft.alerts.duration_ms" type="number" min="500" max="60000" />
          </label>
          <label class="field grow">
            <span>Volume — {{ Math.round(draft.alerts.volume * 100) }}%</span>
            <input v-model.number="draft.alerts.volume" type="range" min="0" max="1" step="0.05" />
          </label>
        </div>

        <!-- Every control here previews against the draft, so you can dial a kind
             in by ear before saving anything to the overlay. -->
        <div class="kinds">
          <div class="kind-head">
            <span>Kind</span><span>Label</span><span>Accent</span><span>Sound</span><span></span>
          </div>
          <div v-for="(kind, name) in draft.alerts.kinds" :key="name" class="kind-row">
            <span class="kind-name" :style="{ borderColor: kind.accent }">{{ name }}</span>
            <input v-model="kind.label" />
            <input v-model="kind.accent" type="color" />
            <select v-model="kind.sound">
              <option v-for="sound in SOUND_NAMES" :key="sound" :value="sound">{{ sound }}</option>
            </select>
            <button class="icon" title="Preview" @click="playSound(kind.sound, draft.alerts.volume)">
              ▶
            </button>
          </div>
        </div>

        <div class="row">
          <button class="primary" @click="saveConfig">Save Settings</button>
          <button @click="revertConfig">Revert</button>
        </div>
      </section>
    </div>
  </main>
</template>

